package cn.mop.api;
import cn.mop.domain.DomainException;
import cn.mop.domain.assetexport.AssetExportJobState;
import cn.mop.domain.assetexport.AssetExportJobState.*;
import org.junit.jupiter.api.Test;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Explicit state/authorization inputs only; no durable queue, real leases, OSS or download grant. */
class AssetExportJobStateTest {
    final UUID tenant=UUID.randomUUID(),actor=UUID.randomUUID(),job=UUID.randomUUID();final Instant t=Instant.parse("2026-10-04T00:00:00Z");
    Access access(){return new Access(tenant,actor,7,"msp",true);}
    Command command(){return new Command(access(),new Filters(null,null,null,null));}
    AssetExportJobState queued(){return AssetExportJobState.queued(job,command(),t);}
    AssetExportJobState running(){return queued().claim(0,access(),t,Duration.ofSeconds(10));}
    Encoding encoding(){return new Encoding("a".repeat(64),"b".repeat(64),10,0,t);}
    AssetExportJobState prepared(){return running().prepared(1,1,access(),t,encoding());}
    StoredArtifact receipt(){return new StoredArtifact(tenant,job,UUID.randomUUID(),"b".repeat(64),10,t.plusSeconds(1));}
    AssetExportJobState success(){return prepared().stored(2,1,access(),t.plusSeconds(1),receipt());}
    @Test void queuedCommandDoesNotMeanStoredPublishedOrNotified(){var s=queued();assertEquals(State.QUEUED,s.state());assertNull(s.encoding());assertNull(s.artifact());assertFalse(s.persisted());assertFalse(s.actualStoreVerified());assertFalse(s.notificationSent());}
    @Test void fingerprintsAreStableButBindScopeVersionRoleAndRawFilters(){assertEquals(command().fingerprint(),command().fingerprint());assertNotEquals(command().fingerprint(),new Command(access(),new Filters(null,null,null,"")).fingerprint());assertNotEquals(command().fingerprint(),new Command(new Access(tenant,actor,8,"msp",true),command().filters()).fingerprint());assertNotEquals(command().fingerprint(),new Command(new Access(tenant,actor,7,"padmin",true),command().filters()).fingerprint());assertNotEquals(new Command(access(),new Filters(null,null,"a|b","c")).fingerprint(),new Command(access(),new Filters(null,null,"a","b|c")).fingerprint());}
    @Test void invalidFiltersAndUnapprovedRolesCannotFormAcceptedCommands(){assertThrows(DomainException.class,()->new Filters("invented",null,null,null));for(var bad:List.of(new Access(tenant,actor,7,"viewer",true),new Access(tenant,actor,7,"tadmin",true),new Access(tenant,actor,7,"msp",false),new Access(tenant,actor,0,"msp",true)))assertThrows(DomainException.class,()->new Command(bad,command().filters()));}
    @Test void firstClaimCreatesOneExplicitBoundedLease(){var r=running();assertEquals(1,r.version());assertEquals(1,r.attempts().size());assertEquals(1,r.attempts().get(0).fence());assertEquals(t.plusSeconds(10),r.attempts().get(0).leaseUntil());assertEquals(State.RUNNING,r.state());}
    @Test void unexpiredLeaseCannotBeClaimedAgain(){assertThrows(DomainException.class,()->running().claim(1,access(),t.plusSeconds(9),Duration.ofSeconds(10)));}
    @Test void expiryBoundaryAllowsNewFenceAndRetainsCommandIdentity(){var r=running().claim(1,access(),t.plusSeconds(10),Duration.ofSeconds(10));assertEquals(2,r.attempts().get(1).fence());assertEquals(command(),r.command());assertEquals(job,r.jobId());assertEquals(t,r.acceptedAt());}
    @Test void oldFenceCannotPublishAfterTakeover(){var r=prepared().claim(2,access(),t.plusSeconds(10),Duration.ofSeconds(10));assertEquals("LEASE_LOST",assertThrows(DomainException.class,()->r.stored(r.version(),1,access(),t.plusSeconds(11),receipt())).code);}
    @Test void preparedDataReclaimMustReconcileBeforeAnotherUpload(){var r=prepared().claim(2,access(),t.plusSeconds(10),Duration.ofSeconds(10));assertEquals(State.RECONCILING_STORAGE,r.state());assertFalse(r.uploadAttemptAllowed(2,access(),t.plusSeconds(10)));assertEquals(encoding(),r.encoding());}
    @Test void encodingCannotBeReplacedAfterBeingCaptured(){var p=prepared();assertThrows(DomainException.class,()->p.prepared(2,1,access(),t,encoding()));}
    @Test void futureOrPreAcceptanceEncodingIsRejected(){for(Instant time:List.of(t.minusMillis(1),t.plusMillis(1))){var e=new Encoding("a".repeat(64),"b".repeat(64),10,1,time);assertThrows(DomainException.class,()->running().prepared(1,1,access(),t,e));}}
    @Test void unknownStoragePreservesEncodingAndPreventsBlindUpload(){var s=prepared().storageUnknown(2,1,access(),t.plusSeconds(1));assertEquals(State.RECONCILING_STORAGE,s.state());assertTrue(s.storageReconciliationRequired());assertFalse(s.uploadAttemptAllowed(1,access(),t.plusSeconds(1)));assertEquals(encoding(),s.encoding());assertNull(s.artifact());}
    @Test void unknownReclaimPreservesReconciliationStateAndPreparedHash(){var s=prepared().storageUnknown(2,1,access(),t.plusSeconds(1)).claim(3,access(),t.plusSeconds(10),Duration.ofSeconds(10));assertEquals(State.RECONCILING_STORAGE,s.state());assertEquals(encoding(),s.encoding());assertEquals(2,s.attempts().size());}
    @Test void matchingStoredReceiptCanResolveAmbiguousUploadWithoutReencoding(){var s=prepared().storageUnknown(2,1,access(),t.plusSeconds(1));var done=s.stored(3,1,access(),t.plusSeconds(2),receipt());assertEquals(State.SUCCEEDED,done.state());assertEquals(encoding(),done.encoding());assertEquals(1,done.attempts().size());}
    @Test void receiptMustMatchJobTenantHashSizeAndObservedTime(){for(var wrong:List.of(new StoredArtifact(UUID.randomUUID(),job,UUID.randomUUID(),"b".repeat(64),10,t),new StoredArtifact(tenant,UUID.randomUUID(),UUID.randomUUID(),"b".repeat(64),10,t)))assertEquals(404,assertThrows(DomainException.class,()->prepared().stored(2,1,access(),t.plusSeconds(1),wrong)).status);for(var wrong:List.of(new StoredArtifact(tenant,job,UUID.randomUUID(),"c".repeat(64),10,t),new StoredArtifact(tenant,job,UUID.randomUUID(),"b".repeat(64),11,t),new StoredArtifact(tenant,job,UUID.randomUUID(),"b".repeat(64),10,t.minusMillis(1)),new StoredArtifact(tenant,job,UUID.randomUUID(),"b".repeat(64),10,t.plusSeconds(2))))assertThrows(DomainException.class,()->prepared().stored(2,1,access(),t.plusSeconds(1),wrong));}
    @Test void currentOwnerTenantVersionRoleAndActiveStateAreRechecked(){for(var foreign:List.of(new Access(UUID.randomUUID(),actor,7,"msp",true),new Access(tenant,UUID.randomUUID(),7,"msp",true)))assertEquals(404,assertThrows(DomainException.class,()->queued().authorize(foreign)).status);for(var changed:List.of(new Access(tenant,actor,8,"msp",true),new Access(tenant,actor,7,"padmin",true),new Access(tenant,actor,7,"msp",false)))assertEquals(401,assertThrows(DomainException.class,()->queued().authorize(changed)).status);}
    @Test void expiredLeaseCannotStoreOrPrepareEvenAtExactBoundary(){assertEquals("LEASE_LOST",assertThrows(DomainException.class,()->prepared().stored(2,1,access(),t.plusSeconds(10),receipt())).code);assertEquals("LEASE_LOST",assertThrows(DomainException.class,()->running().prepared(1,1,access(),t.plusSeconds(10),encoding())).code);}
    @Test void definiteFailuresRetainPriorCommandAndEncoding(){var p=prepared();var failed=p.failed(2,1,t.plusSeconds(1),Failure.ENCODING_FAILED);assertEquals(State.FAILED,failed.state());assertEquals(encoding(),failed.encoding());assertEquals(p.command(),failed.command());assertThrows(DomainException.class,()->failed.claim(3,access(),t.plusSeconds(20),Duration.ofSeconds(10)));}
    @Test void ambiguityCannotBeReclassifiedAsAnUnrelatedLocalError(){var s=prepared().storageUnknown(2,1,access(),t.plusSeconds(1));assertThrows(DomainException.class,()->s.failed(3,1,t.plusSeconds(2),Failure.SOURCE_UNAVAILABLE));assertEquals(State.FAILED,s.failed(3,1,t.plusSeconds(2),Failure.CONFIRMED_STORAGE_REJECTION).state());}
    @Test void downloadWindowIsExactlyFifteenMinutesAndIsNotAnActualGrant(){var window=success().downloadWindow(access(),t.plusSeconds(2));assertEquals(t.plusSeconds(902),window.expiresAt());assertFalse(window.actualGrantIssued());assertEquals("CURRENT_OBJECT_AUTHORIZATION_STORAGE_AND_AUDIT_REQUIRED",window.remainingGate());}
    @Test void notStoredOrRevokedJobsCannotOfferADownloadWindow(){assertThrows(DomainException.class,()->prepared().downloadWindow(access(),t.plusSeconds(1)));assertThrows(DomainException.class,()->success().downloadWindow(new Access(tenant,actor,8,"msp",true),t.plusSeconds(2)));assertThrows(DomainException.class,()->success().downloadWindow(access(),t));}
    @Test void invalidTimestampsLeasesAndDescriptorsAreRejectedWithoutEcho(){for(Duration lease:List.of(Duration.ZERO,Duration.ofMinutes(11),Duration.ofNanos(1)))assertThrows(DomainException.class,()->queued().claim(0,access(),t,lease));assertThrows(DomainException.class,()->queued().claim(0,access(),t.plusNanos(1),Duration.ofSeconds(1)));var e=assertThrows(DomainException.class,()->new Encoding("SYNTHETIC_SECRET","b".repeat(64),10,0,t));assertFalse(e.getMessage().contains("SYNTHETIC"));assertThrows(DomainException.class,()->new Encoding("a".repeat(64),"b".repeat(64),10,1001,t));}
    @Test void staleLogicalVersionsAndRegressingObservationTimeAreRejected(){assertEquals("VERSION_CONFLICT",assertThrows(DomainException.class,()->running().prepared(0,1,access(),t,encoding())).code);assertThrows(DomainException.class,()->running().prepared(1,1,access(),t.minusMillis(1),encoding()));}
    @Test void completedJobsDoNotAcceptMoreTransitions(){var s=success();assertThrows(DomainException.class,()->s.claim(s.version(),access(),t.plusSeconds(20),Duration.ofSeconds(10)));assertThrows(DomainException.class,()->s.storageUnknown(s.version(),1,access(),t.plusSeconds(2)));assertThrows(DomainException.class,()->s.failed(s.version(),1,t.plusSeconds(2),Failure.SOURCE_UNAVAILABLE));}
    @Test void leaseAndDownloadTimeOverflowFailWithoutMutation(){Instant end=Instant.parse("9999-12-31T23:59:59.999Z");var q=AssetExportJobState.queued(job,command(),end);assertThrows(DomainException.class,()->q.claim(0,access(),end,Duration.ofSeconds(1)));assertEquals(State.QUEUED,q.state());assertThrows(DomainException.class,()->success().downloadWindow(access(),end));}
    @Test void snapshotsAndAttemptHistoryAreImmutable(){var q=queued();var r=q.claim(0,access(),t,Duration.ofSeconds(10));assertEquals(State.QUEUED,q.state());assertEquals(State.RUNNING,r.state());assertThrows(UnsupportedOperationException.class,()->r.attempts().clear());}
    @Test void evenUploadEligibilityRequiresFreshAccessFenceAndLeaseTime(){var p=prepared();assertTrue(p.uploadAttemptAllowed(1,access(),t));assertThrows(DomainException.class,()->p.uploadAttemptAllowed(1,access(),t.plusSeconds(10)));assertThrows(DomainException.class,()->p.uploadAttemptAllowed(2,access(),t));assertThrows(DomainException.class,()->p.uploadAttemptAllowed(1,new Access(tenant,actor,8,"msp",true),t));}
    @Test void confirmedAbsenceAllowsOnlyTheSamePreparedBytesToBeRetried(){var r=prepared().claim(2,access(),t.plusSeconds(10),Duration.ofSeconds(10));assertFalse(r.uploadAttemptAllowed(2,access(),t.plusSeconds(10)));var retry=r.confirmedStorageAbsent(3,2,access(),t.plusSeconds(11));assertEquals(encoding(),retry.encoding());assertTrue(retry.uploadAttemptAllowed(2,access(),t.plusSeconds(11)));assertThrows(DomainException.class,()->retry.prepared(4,2,access(),t.plusSeconds(12),encoding()));}
    @Test void queuedMissingOrChangedAuthorizationCanBeRecordedWithoutClaimingWork(){for(Access missing:Arrays.asList(null,new Access(tenant,actor,8,"msp",true),new Access(tenant,actor,7,"msp",false))){var failed=queued().authorizationDenied(0,missing,t);assertEquals(State.FAILED,failed.state());assertEquals(Failure.AUTHORIZATION_CHANGED,failed.failure());assertEquals(0,failed.attempts().size());}assertThrows(DomainException.class,()->queued().authorizationDenied(0,access(),t));}
    @Test void expiredRevokedJobRetainsPreparedFactsForOrphanReview(){var p=prepared();assertThrows(DomainException.class,()->p.authorizationDenied(2,null,t.plusSeconds(9)));var failed=p.authorizationDenied(2,null,t.plusSeconds(10));assertEquals(State.FAILED,failed.state());assertEquals(encoding(),failed.encoding());assertTrue(failed.possibleOrphanNeedsReview());assertFalse(failed.notificationSent());assertThrows(DomainException.class,()->failed.downloadWindow(access(),t.plusSeconds(11)));}
    @Test void foreignActorCannotTurnAnotherJobIntoAnAuthorizationFailure(){assertEquals(404,assertThrows(DomainException.class,()->queued().authorizationDenied(0,new Access(tenant,UUID.randomUUID(),7,"msp",false),t)).status);assertThrows(DomainException.class,()->success().authorizationDenied(success().version(),null,t.plusSeconds(20)));}
    @Test void boundedAttemptHistoryRefusesFurtherClaimsWithoutDroppingPriorAttempts(){var s=queued();for(int i=0;i<1000;i++)s=s.claim(s.version(),access(),t.plusMillis(i),Duration.ofMillis(1));var full=s;assertEquals(1000,full.attempts().size());assertThrows(DomainException.class,()->full.claim(full.version(),access(),t.plusMillis(1000),Duration.ofMillis(1)));}

}
